arguments.file_text:
@page "/catalog"
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/catalog" class="catalog-filter-form">
    <div class="filter-controls">
        <input type="text" name="Search" value="@Search" placeholder="Search by name or keyword..." class="form-input" />
        <select name="DepartmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
        <button type="submit" class="btn btn-primary">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

<p class="results-count">Showing @courses.Count course(s)</p>

@if (courses.Any())
{
    <table class="catalog-table">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/course/@course.Id">View Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <p>No courses found matching your criteria.</p>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/course/{Id:int}"
@inject ICatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="/catalog">Back to Catalog</a>
}
else
{
    <PageTitle>@course.Title - Course Details</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/catalog">Catalog</a> &rsaquo;
        <span>@course.Code</span>
    </nav>

    <div class="course-detail">
        <div class="course-detail-header">
            <h1>@course.Title</h1>
            <span class="course-code-badge">@course.Code</span>
        </div>

        <div class="course-meta">
            <span><strong>Credits:</strong> @course.Credits</span>
            <span><strong>Department:</strong> @course.DepartmentName</span>
            <span><strong>Schedule:</strong> @course.Schedule</span>
        </div>

        <div class="course-description">
            <h2>Description</h2>
            <p>@course.Description</p>
        </div>

        <div class="instructor-section">
            <h2>Instructor</h2>
            <h3>@course.InstructorName</h3>
            <p>@course.InstructorBio</p>
        </div>

        <div class="course-actions">
            <a href="/enroll?CourseId=@course.Id" class="btn btn-primary">Enroll in This Course</a>
            <a href="/catalog" class="btn btn-secondary">Back to Catalog</a>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll in a Course</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="confirmation-message">
        <h2>Enrollment Request Submitted!</h2>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
        <p>Student ID: @Model.StudentId</p>
        <a href="/catalog" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    @if (validationError)
    {
        <div class="validation-error">
            <p>Please fill in all fields correctly.</p>
        </div>
    }

    <form method="post" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required class="form-input" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" required class="form-input" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required class="form-select">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code - @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private bool validationError;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContext.Request.Method))
        {
            if (CatalogService.SubmitEnrollment(Model))
            {
                submitted = true;
            }
            else
            {
                validationError = true;
            }
        }
    }

    [CascadingParameter]
    public HttpContext HttpContext { get; set; } = default!;
}

